// newInviteToken returns 32 random bytes from crypto/rand, in unpadded base64url (43 characters).
func newInviteToken() string {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		panic(err) // crypto/rand does not fail on supported platforms
	}
	return base64.RawURLEncoding.EncodeToString(b)
}

// InviteTokenHash returns the SHA-256 of an invite token, in hex. The store keeps this hash, never the token.
func InviteTokenHash(token string) string {
	sum := sha256.Sum256([]byte(token))
	return hex.EncodeToString(sum[:])
}

func normEmail(email string) string { return strings.ToLower(strings.TrimSpace(email)) }

