// CreateInvite invites an email address to join an organization with a role. The returned invite carries the token to
// send; it is the only place the token exists. A pending invite to the same address (ignoring case) is revoked, so
// only the newest token works.
func (s *Store) CreateInvite(orgID, email string, role Role, invitedBy string, now time.Time) (Invite, error) {
	email = strings.TrimSpace(email)
	if !validEmail(email) {
		return Invite{}, invalid("an invite needs a valid email address")
	}
	if !role.Valid() || role == RoleOwner {
		return Invite{}, invalid("an invite's role is admin, billing, member or viewer")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[orgID]; !ok {
		return Invite{}, ErrNotFound
	}
	if uid, ok := s.usersByEmail[normEmail(email)]; ok {
		if _, member := s.members[memberKey{orgID, uid}]; member {
			return Invite{}, ErrAlreadyMember
		}
	}
	token := newInviteToken()
	inv := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, TokenHash: InviteTokenHash(token), InvitedBy: invitedBy, CreatedAt: now.UTC()}
	t := now.UTC()
	for id, old := range s.invites {
		if old.OrgID == orgID && normEmail(old.Email) == normEmail(email) && old.AcceptedAt == nil && old.RevokedAt == nil {
			old.RevokedAt = &t
			s.invites[id] = old
		}
	}
	s.invites[inv.ID] = inv
	inv.Token = token
	return inv, nil
}

// Invite returns one of an organization's invites.
func (s *Store) Invite(orgID, id string) (Invite, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invites[id]
	if !ok || inv.OrgID != orgID {
		return Invite{}, false
	}
	return inv, true
}

// Invites returns an organization's invites that were neither accepted nor revoked, oldest first. Expired ones are
// included; see PendingInvites.
func (s *Store) Invites(orgID string) []Invite {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Invite{}
	for _, inv := range s.invites {
		if inv.OrgID == orgID && inv.AcceptedAt == nil && inv.RevokedAt == nil {
			out = append(out, inv)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// PendingInvites returns an organization's invites that can still be accepted at now: neither accepted, revoked nor
// expired. Oldest first.
func (s *Store) PendingInvites(orgID string, now time.Time) []Invite {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Invite{}
	for _, inv := range s.invites {
		if inv.OrgID == orgID && inv.AcceptedAt == nil && inv.RevokedAt == nil && !inv.expired(now) {
			out = append(out, inv)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

