// makes them a member with the invite's role and gives them a first API key. An unknown or revoked token is
// ErrNotFound, an accepted one ErrInviteUsed and one older than InviteLifetime ErrInviteExpired.
func (s *Store) AcceptInvite(token, name string, now time.Time) (User, Member, APIKey, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	hash := InviteTokenHash(token)
	var inv Invite
	found := false
	for _, i := range s.invites {
		if i.TokenHash == hash {
			inv, found = i, true
			break
		}
	}
	if !found || inv.RevokedAt != nil {
		return User{}, Member{}, APIKey{}, ErrNotFound
	}
	if inv.AcceptedAt != nil {
		return User{}, Member{}, APIKey{}, ErrInviteUsed
	}
	if inv.expired(now) {
		return User{}, Member{}, APIKey{}, ErrInviteExpired
	}

