func TestInviteTokens(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	inv, err := s.CreateInvite(a.ID, "new@example.com", RoleMember, "usr_000001", t0)
	if err != nil {
		t.Fatal(err)
	}
	if raw, err := base64.RawURLEncoding.DecodeString(inv.Token); err != nil || len(raw) != 32 || len(inv.Token) != 43 {
		t.Fatalf("token %q is not 32 random bytes in unpadded base64url", inv.Token)
	}
	other, _ := s.CreateInvite(a.ID, "other@example.com", RoleMember, "usr_000001", t0)
	if other.Token == inv.Token {
		t.Fatal("two invites got the same token")
	}
	stored, ok := s.Invite(a.ID, inv.ID)
	if !ok || stored.Token != "" || stored.TokenHash != InviteTokenHash(inv.Token) {
		t.Fatalf("stored invite = %+v", stored)
	}
	state, err := json.Marshal(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(state), inv.Token) {
		t.Fatal("the exported state holds a token")
	}
	pending := s.PendingInvites(a.ID, t0)
	if len(pending) != 2 || pending[0].Token != "" {
		t.Fatalf("pending = %+v", pending)
	}
	s2, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if _, _, _, err := s2.AcceptInvite(inv.Token, "New", t0); err != nil {
		t.Fatalf("the invite does not work after FromState: %v", err)
	}
}

func TestInviteReplacesPendingInvites(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	b := newOrg(t, s, "B")
	first, _ := s.CreateInvite(a.ID, "Ann@Example.com", RoleMember, "usr_000001", t0)
	elsewhere, _ := s.CreateInvite(b.ID, "ann@example.com", RoleMember, "usr_000001", t0)
	second, err := s.CreateInvite(a.ID, "ann@example.com ", RoleViewer, "usr_000001", t0.Add(time.Hour))
	if err != nil {
		t.Fatal(err)
	}
	if _, _, _, err := s.AcceptInvite(first.Token, "Ann", t0.Add(time.Hour)); !errors.Is(err, ErrNotFound) {
		t.Fatalf("the replaced token: %v", err)
	}
	if pending := s.PendingInvites(a.ID, t0.Add(time.Hour)); len(pending) != 1 || pending[0].ID != second.ID {
		t.Fatalf("pending = %+v", pending)
	}
	if pending := s.PendingInvites(b.ID, t0.Add(time.Hour)); len(pending) != 1 || pending[0].ID != elsewhere.ID {
		t.Fatalf("another organization's invite was revoked: %+v", pending)
	}
	if _, _, _, err := s.AcceptInvite(second.Token, "Ann", t0.Add(time.Hour)); err != nil {
		t.Fatalf("the newest token: %v", err)
	}
}

